"""Embed the Baloo 2 font as a data URL → css/font.css (so the font also loads when index.html is opened from disk:
Chrome blocks file:// font loads as cross-origin).  Run: python3 tools/embed_font.py"""
import base64
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
b = base64.b64encode((ROOT / 'assets/fonts/Baloo2.woff2').read_bytes()).decode()
(ROOT / 'css/font.css').write_text(
    "/* generated by tools/embed_font.py — Baloo 2 (SIL Open Font License) */\n"
    "@font-face { font-family: 'Baloo 2'; src: url(data:font/woff2;base64," + b + ") format('woff2'); "
    "font-weight: 400 800; font-display: block; }\n", encoding='utf-8')
print('css/font.css', len(b) // 1024, 'KB')
